type Ride = { id: string; role: 'motorista'; origin: string; destination: string; day: Day; departure: string; arrival: string; seats: number; detour: number; meeting: string; privateAddress?: string; intermediates?: string[]; priceModel: 'gasolina' | 'total' | 'gratis' | 'custom'; customPrice?: number; distanceKm: number; consumption: number; fuelPrice: number; parking: number; recurring: boolean; driver: string; rating: number; verified: boolean };
type CarpoolRequest = { id: string; origin: string; destination: string; day: Day; wantedHour: string; tolerance: number; people: number; meetingRadius: number; privateAddress?: string; intermediates?: string[]; recurring: boolean; status: 'ativa' | 'atendida' | 'cancelada' };
