const timeToMinutes = (value: string) => { const [hours, minutes] = value.split(':').map(Number); return hours * 60 + minutes; };
const money = (value: number) => Number.isFinite(value) && value >= 0 ? value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) : 'Indisponível para este grupo';
function rideCost(ride: Ride, people: number) { const fuel = ride.distanceKm / ride.consumption * ride.fuelPrice; const shared = ride.priceModel === 'gratis' ? 0 : ride.priceModel === 'gasolina' ? fuel : ride.priceModel === 'custom' ? (ride.customPrice ?? 0) : fuel + ride.parking; const occupants = Math.max(1, people + 1); if (people > ride.seats) return { fuel: Number.NaN, parking: 0, total: Number.NaN, perPerson: Number.NaN, occupants }; return { fuel, parking: ride.priceModel === 'total' ? ride.parking : 0, total: shared, perPerson: shared / occupants, occupants }; }
const isDay = (value: unknown): value is Day => DAYS.some((item) => item.value === value);
const isPriceModel = (value: unknown): value is Ride['priceModel'] => value === 'gasolina' || value === 'total' || value === 'gratis' || value === 'custom';
function isValidRide(value: unknown): value is Ride {
  if (!value || typeof value !== 'object') return false;
  const ride = value as Partial<Ride>;
  const seats = ride.seats;
  const detour = ride.detour;
  if (typeof seats !== 'number' || !Number.isInteger(seats) || seats < 0 || seats > 8) return false;
  if (typeof detour !== 'number' || !Number.isInteger(detour) || detour < 0 || detour > 120) return false;
  return typeof ride.id === 'string' && ride.id.length <= 80 && ride.role === 'motorista' && typeof ride.origin === 'string' && typeof ride.destination === 'string' && isDay(ride.day) && typeof ride.departure === 'string' && typeof ride.arrival === 'string' && typeof ride.meeting === 'string' && ride.meeting.length <= 120 && isPriceModel(ride.priceModel) && typeof ride.distanceKm === 'number' && ride.distanceKm > 0 && ride.distanceKm <= 100 && typeof ride.consumption === 'number' && ride.consumption > 0 && ride.consumption <= 40 && typeof ride.fuelPrice === 'number' && ride.fuelPrice >= 0 && ride.fuelPrice <= 100 && typeof ride.parking === 'number' && ride.parking >= 0 && ride.parking <= 1000 && typeof ride.recurring === 'boolean' && typeof ride.driver === 'string' && ride.driver.length <= 80 && typeof ride.rating === 'number' && ride.rating >= 0 && ride.rating <= 5 && typeof ride.verified === 'boolean' && (typeof ride.privateAddress === 'undefined' || typeof ride.privateAddress === 'string') && (typeof ride.intermediates === 'undefined' || Array.isArray(ride.intermediates));
}
function readSavedRides() {
  if (typeof window === 'undefined') return seedRides;
  try {
    const saved = window.localStorage.getItem('vaga-certa-rides');
    if (saved) { const parsed: unknown = JSON.parse(saved); const valid = Array.isArray(parsed) ? parsed.filter(isValidRide) : []; if (valid.length) return valid; }
  } catch { /* storage can be unavailable in private browsing */ }
  return seedRides;
}
function readSavedIds(key: string) {
  if (typeof window === 'undefined') return [];
  try { const saved = window.localStorage.getItem(key); const parsed: unknown = saved ? JSON.parse(saved) : []; return Array.isArray(parsed) ? parsed.filter((item): item is string => typeof item === 'string' && item.length <= 80) : []; } catch { return []; }
}
function readSavedRequests() { if (typeof window === 'undefined') return [] as CarpoolRequest[]; try { const saved = window.localStorage.getItem('vaga-certa-requests'); const parsed: unknown = saved ? JSON.parse(saved) : []; return Array.isArray(parsed) ? parsed.filter((item): item is CarpoolRequest => Boolean(item && typeof item === 'object' && typeof (item as CarpoolRequest).id === 'string' && typeof (item as CarpoolRequest).origin === 'string' && typeof (item as CarpoolRequest).destination === 'string' && isDay((item as CarpoolRequest).day) && typeof (item as CarpoolRequest).wantedHour === 'string' && Number.isInteger((item as CarpoolRequest).tolerance) && Number.isInteger((item as CarpoolRequest).people) && Number.isInteger((item as CarpoolRequest).meetingRadius) && (typeof (item as CarpoolRequest).privateAddress === 'undefined' || typeof (item as CarpoolRequest).privateAddress === 'string') && (typeof (item as CarpoolRequest).intermediates === 'undefined' || Array.isArray((item as CarpoolRequest).intermediates)) && typeof (item as CarpoolRequest).recurring === 'boolean' && ['ativa', 'atendida', 'cancelada'].includes((item as CarpoolRequest).status))) : []; } catch { return []; } }
function readSavedProfile(): LocalProfile | null { if (typeof window === 'undefined') return null; try { const saved = window.localStorage.getItem('vaga-certa-profile'); const parsed: unknown = saved ? JSON.parse(saved) : null; if (!parsed || typeof parsed !== 'object') return null; const value = parsed as Partial<LocalProfile>; return typeof value.name === 'string' && value.name.length <= 80 && typeof value.email === 'string' && value.email.length <= 160 && typeof value.course === 'string' && value.course.length <= 100 && typeof value.verified === 'boolean' ? value as LocalProfile : null; } catch { return null; } }
const dayLabel = (day: Day) => DAYS.find((item) => item.value === day)?.label ?? day;
const cleanStops = (stops: string[]) => stops.map((stop) => stop.trim()).filter(Boolean).slice(0, 3);
const routeStopsLabel = (stops?: string[]) => cleanStops(stops ?? []).join(' · ');
function statusFor(pct: number) { if (pct >= 90) return { label: 'Risco alto', tone: 'danger', copy: 'Pouca margem para chegar sem plano B.' }; if (pct >= 70) return { label: 'Atenção', tone: 'warning', copy: 'A ocupação pode mudar rápido neste período.' }; return { label: 'Boa margem', tone: 'good', copy: 'Há espaço projetado, mas a previsão é uma faixa.' }; }
function occupancyBand(pct: number) { if (pct < 25) return 'Muito vazio'; if (pct < 45) return 'Vazio'; if (pct < 65) return 'Moderado'; if (pct < 80) return 'Cheio'; if (pct < 92) return 'Muito cheio'; return 'Provavelmente lotado'; }

type MapPoint = { lat: number; lon: number; label: string };
type LocalProfile = { name: string; email: string; course: string; verified: boolean };
type CarpoolGroup = { id: string; name: string; neighborhood: string; day: Day; route: string; intermediates: string[]; members: { name: string; role: 'motorista' | 'passageiro'; verified: boolean }[]; maxMembers: number };
const campusPoint: MapPoint = { lat: -22.9797, lon: -43.2333, label: 'PUC-Rio · Gávea' };
const mapEmbedUrl = (point: MapPoint) => { const delta = 0.008; return `https://www.openstreetmap.org/export/embed.html?bbox=${point.lon - delta},${point.lat - delta},${point.lon + delta},${point.lat + delta}&layer=mapnik&marker=${point.lat},${point.lon}`; };
